  },
  beforeUnmount(){this._closed=true;clearTimeout(this._tourTimer);this.finishAboutExit();this._compactQuery?.removeEventListener('change',this.syncCompact);this.rememberHall();this._scene?.dispose();this._keyboard?.dispose();this._stopCollectionBackdrop?.();window.removeEventListener('theme-change',this.syncTheme);window.removeEventListener('museum-views-updated',this.syncOwnViews);window.removeEventListener('site-music-state',this.syncMusic);window.removeEventListener('message',this.onShowcasePlayback);this.$refs.dialog?.close();document.body.style.overflow=this._overflow||'';},
  methods:{
    onShowcasePlayback(event){
