    },
    nextTourStep(){this.showTourStep(this.tourIndex+1);},
    toggleTour(){this.tourPaused=!this.tourPaused;if(this.tourPaused)clearTimeout(this._tourTimer);else this.scheduleTour();},
    async finishTour(){
      if(!this.tourActive)return;
      clearTimeout(this._tourTimer);this.tourActive=false;this.tourPaused=true;this.tourMoving=true;this.travelling=true;const saved=this._tourReturn;this.directoryExpanded=false;this.readingExpanded=false;
      if(this.showcaseFrame){this.showcaseCycle+=1;this.panelOpen=false;this.tourMoving=false;this.travelling=false;this._tourReturn=null;if(this.showcaseLoop)this._tourTimer=setTimeout(()=>this.startTour(),650);return;}
      this.panelOpen=false;
      if(saved?.pose)await this._scene?.restorePose(saved.pose);
      if(this._closed)return;
      Object.assign(this,saved?.ui||{});this.tourPaused=false;this.tourMoving=false;this.travelling=false;this._tourReturn=null;
    },
    toggleDirectory(){this.hoveredCatalogueId='';this.directoryExpanded=!this.directoryExpanded;},
    focusCatalogue(view,event){this.focusedCatalogueId=view&&event?.target?.matches(':focus-visible')?view.id:'';},
    hoverCatalogue(view){this.hoveredCatalogueId=this.area==='directory'&&!this.travelling?(view?.id||''):'';},
    previewView(view){this.chosenId=view.id;this.selected=view;this._scene?.setExhibition(view);this.rememberHall();},
    syncOwnViews(){this.ownViews=ownMuseumViews();},
    async returnToOrigin(){if(this.departing||!this.returnOrigin)return;this.departing=true;this.rememberHall();updateMuseumSession({resumeOnViews:false});await coverViewTransition();if(!this._closed)window.dispatchEvent(new CustomEvent('museum-return-origin',{detail:this.returnOrigin}));},
    continueFromHall(){const action=this.nextAction;if(action.kind==='tour')this.startTour();else if(action.kind==='explore')this.visit('directory');else if(action.kind==='create')this.visit('compose');else this.enterView(action.view);},
    rememberHall(){if(this.showcaseFrame)return;updateMuseumSession({hall:{area:this.area,angle:this.hallAngle,chosenId:this.chosenId,selectedId:this.selected?.id||'',query:this.query,collectionScope:this.collectionScope}});},
    selectFirst(){if(!this.selected){const id=this.chosenId||this.lastView?.id||museumSession().hall?.selectedId;this.selected=[...this.ownViews,...this.collection].find(view=>view.id===id)||this.collection[0]||null;}this._scene?.setExhibition(this.selected);},
    select(view){this.chosenId=view.id;this.selected=view;this._scene?.setExhibition(view);this.visit('collection');},
    async changeHallAngle(){
      if(this.departing||this.area!=='hall')return;
      this._keyboard?.clear();this.hallAngle=this.hallAngle==='front'?'across':'front';
      const sequence=(this._visitSequence||0)+1;this._visitSequence=sequence;
      this.changingHallAngle=true;
      await this._scene?.setHallAngle(this.hallAngle);
      if(this._closed||sequence!==this._visitSequence)return;
      this.changingHallAngle=false;this.rememberHall();
    },
    finishAboutExit(){this._resolveAboutExit?.();this._resolveAboutExit=null;this._aboutExitPromise=null;},
    async visit(area){
      if(this.departing || (area===this.area && this.stationVisible && (this.panelOpen || (area==='collection'&&!this.walkingAway))))return;
      this._keyboard?.clear();this.stationVisible=true;this.walkingAway=false;this.hoveredCatalogueId='';
      this.travelling=true;this.changingHallAngle=false;
      const sequence=(this._visitSequence||0)+1;this._visitSequence=sequence;
      if(!this.compact && this.area==='about' && (this.panelOpen||this._aboutExitPromise)){
        if(!this._aboutExitPromise){this._aboutExitPromise=new Promise(resolve=>{this._resolveAboutExit=resolve;});this.panelOpen=false;}
        await this._aboutExitPromise;
        if(this._closed||sequence!==this._visitSequence)return;
      }
      this.directoryExpanded=false;this.readingExpanded=false;this.area=area;
      this.panelOpen=this.compact&&['directory','compose','about'].includes(area);
      await this._scene?.go(area);
      if(this._closed||sequence!==this._visitSequence)return;
      this.travelling=false;this.panelOpen=['directory','compose','about'].includes(area);this.rememberHall();
    },
    
    escape(){if(this.tourActive){this.finishTour();return;}if(this.readingExpanded){this.readingExpanded=false;return;}if(this.directoryExpanded){this.directoryExpanded=false;return;}if(this.area!=='hall')this.visit('hall');else this.website();},
    openProject(event){if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();this.navigate('/viewgallery');},
    onWalk(){
      if(this.departing)return;
      // Manual movement takes over an in-flight visit before its promise can
      // reopen a panel at a station the visitor never reached.
      if(this.travelling||this.changingHallAngle){this.changingHallAngle=false;this._visitSequence=(this._visitSequence||0)+1;this.travelling=false;}
    },
    onAttention({area}){
      if(this.departing||this.tourActive||this.travelling||this.changingHallAngle||this.directoryExpanded||this.readingExpanded)return;
      if(!area){this.stationVisible=false;return;}
      this.stationVisible=true;this.walkingAway=false;
      if(area!==this.area){this.area=area;this.hoveredCatalogueId='';}
      this.panelOpen=area!=='collection';
    },
    walk(p){this._scene?.setMovement(p.x,p.y);},
    toggleTheme(){document.getElementById('toggle-theme')?.click();},syncTheme(){beginExhibitionTheme(this.$refs.dialog);this.dark=document.body.classList.contains('dark-mode');this._scene?.setTheme(this.dark);},
    toggleMusic(){window.dispatchEvent(new CustomEvent('site-music-command',{detail:{action:'toggle'}}));},syncMusic(event){this.musicPlaying=!!event.detail.playing;},
    website(){updateMuseumSession({mode:'article',resumeOnViews:false});this.$emit('website');},
    async navigate(path){
      if(this.departing)return;
      if(path==='/views'){this.visit('hall');return;}
      this.departing=true;updateMuseumSession({resumeOnViews:false});this.rememberHall();
      try{await coverViewTransition();if(!this._closed)await this.$router.push(path);}
      finally{if(!this._closed)this.departing=false;setTimeout(revealViewTransition,420);}
    },
    async enterView(view,resume=true){
      if(this.departing||!view?.id)return;
      this._visitSequence=(this._visitSequence||0)+1;
      this.departing=true;this.entryError='';this.selected=view;this.hoveredCatalogueId='';
      this.panelOpen=false;this.directoryExpanded=false;this.readingExpanded=false;this.area='collection';
      this.stationVisible=true;this.walkingAway=false;this.travelling=true;
      this._keyboard?.clear();this._scene?.setExhibition(view);this.rememberHall();
      updateMuseumSession({mode:'museum',resumeOnViews:false});
      try {
        // One uninterrupted walk passes through the entrance. Loading runs
        // alongside it, with the pavilion visible until the threshold.
        let prepared=false;
        await Promise.all([
          this._scene?.go('entry').then(()=>{if(!this._closed&&this.departing&&!prepared)this.entryWaiting=true;}),
          prepareMuseumVisit(view.id).then(()=>{prepared=true;}),
        ]);
        if(this._closed)return;
        this.entryWaiting=false;
        await coverViewTransition();
        if(this._closed)return;
        updateMuseumSession({lastView:{id:view.id,title:view.title,position:resume?museumReturnPosition(view.id):null}});
        await this.$router.push(`/view/${view.id}`);
      } catch {
        this.departing=false;this.travelling=false;this.entryWaiting=false;
        this.entryError='This exhibition could not open. Please try again.';
        revealViewTransition();
      }
    },
    dateTime(value){const date=new Date(typeof value==='string'&&/^\d+$/.test(value)?Number(value):value);return Number.isNaN(date.getTime())?'':date.toISOString();},
    dateLabel(value){return value?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)):'';},
  },
};
